                    "<img src=\"images/572753fae3a24d299d0f860db6bc07bd.png\" class=\"exam-img\" style=\"max-width:100%; vertical-align:middle; margin:4px 0;\">\r                             or\r                             <img src=\"images/0ec548c55bc3455b817f10c644014c57.png\" class=\"exam-img\" style=\"max-width:100%; vertical-align:middle; margin:4px 0;\">",
